(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;root.QCFAudit=api})(typeof globalThis!=='undefined'?globalThis:this,function(){
  const stable=x=>x&&typeof x==='object'?(Array.isArray(x)?`[${x.map(stable)}]`:`{${Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+stable(x[k])).join(',')}}`):JSON.stringify(x),hash=s=>{let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16).padStart(8,'0')};
  class AuditChain{constructor(){this.rows=[]}append(type,payload){const prev=this.rows.at(-1)?.hash||'00000000',seq=this.rows.length+1,body={seq,type,payload,prev},row={...body,hash:hash(stable(body)),at:new Date().toISOString()};this.rows.push(row);return row}verify(){let prev='00000000';for(const row of this.rows){const body={seq:row.seq,type:row.type,payload:row.payload,prev};if(row.prev!==prev||hash(stable(body))!==row.hash)return{valid:false,brokenAt:row.seq};prev=row.hash}return{valid:true,count:this.rows.length,head:prev}}}
  class Metrics{constructor(){this.values=new Map()}inc(name,n=1){this.values.set(name,(this.values.get(name)||0)+n)}set(name,v){this.values.set(name,v)}snapshot(){return Object.fromEntries(this.values)}}
  class TokenBucket{constructor(rate=5,burst=10){this.rate=rate;this.capacity=burst;this.tokens=burst;this.at=Date.now()}take(n=1){const now=Date.now();this.tokens=Math.min(this.capacity,this.tokens+(now-this.at)/1000*this.rate);this.at=now;if(this.tokens<n)return false;this.tokens-=n;return true}}
  function validateEndpoint(value,allowHosts=[]){if(!value)return{valid:true,local:true};try{const u=new URL(value);const local=u.protocol==='model:';const allowed=local||(u.protocol==='https:'&&allowHosts.includes(u.hostname));return{valid:allowed,local,host:u.hostname||'local'}}catch(e){return{valid:false,local:false}}}
  function sanitizeConfig(x={}){return{type:['math','ai','hybrid'].includes(x.type)?x.type:'math',weight:Math.max(0,Math.min(2,+x.weight||1)),endpoint:String(x.endpoint||'').slice(0,240)}}
  return{AuditChain,Metrics,TokenBucket,validateEndpoint,sanitizeConfig,stable,hash};
});
